#!/usr/bin/env python3
"""Run one session of commands (each arg a command) on the original (or MINE with -m), save, and print
replies plus the saved fill_patterns/region_types entries that differ from the default project, and the
library entries of kinds fill-pattern / filled-region-type that are new or renamed.
usage: fp.py [-m] [-f file]... cmd...
"""
import os, subprocess, sys, tempfile, shutil, json
ORIG = '/workspace/executable'
MINE = os.environ.get('MINE', '/tmp/styles-agent/fills/repo/target/release/bimcraft-cli')
a = sys.argv[1:]
exe = ORIG
files = []
raw = False
while a and a[0].startswith('-'):
    if a[0] == '-m': exe = MINE; a = a[1:]
    elif a[0] == '-f': files.append(a[1]); a = a[2:]
    elif a[0] == '-r': raw = True; a = a[1:]
    else: break
d = tempfile.mkdtemp(prefix='fp')
for f in files: shutil.copy(f, d)
args = [exe, 'run']
for c in a:
    args += ['--cmd', c]
args += ['--save', 'x.bimcraft']
p = subprocess.run(args, cwd=d, capture_output=True)
print(p.stdout.decode('utf-8', 'replace').strip())
if p.stderr: print('ERR:', p.stderr.decode('utf-8', 'replace').strip())
default = json.load(open('/tmp/styles-agent/fills/default.bimcraft'))
if os.path.exists(os.path.join(d, 'x.bimcraft')):
    txt = open(os.path.join(d, 'x.bimcraft')).read()
    doc = json.loads(txt)
    for sec in ('fill_patterns', 'region_types'):
        cur = doc.get(sec, {})
        dflt = default.get(sec, {})
        keys = list(cur.keys())
        if keys != list(dflt.keys()):
            print(' [%s] keys: %s' % (sec, keys))
        for k, v in cur.items():
            dv = dflt.get(k)
            if dv is None or json.dumps(dv) != json.dumps(v):
                # print with the real text formatting
                print(' [%s] %r: %s' % (sec, k, json.dumps(v, ensure_ascii=False)))
        for k in dflt:
            if k not in cur: print(' [%s] gone: %r' % (sec, k))
    lib = doc['library']
    for k, v in lib.items():
        if v['kind'] in ('fill-pattern', 'filled-region-type'):
            dv = default['library'].get(k)
            if dv is None or dv['name'] != v['name'] or dv['kind'] != v['kind']:
                print(' [lib] %s %s' % (k, v))
    for k, v in default['library'].items():
        if v['kind'] in ('fill-pattern', 'filled-region-type') and k not in lib:
            print(' [lib] gone %s %s' % (k, v))
    if raw:
        i = txt.find('"fill_patterns"'); j = txt.find('"region_types"'); k2 = txt.find('"text_types"')
        print(txt[i:k2])
    print(' top:', ','.join(doc.keys()))
for f in sorted(os.listdir(d)):
    if f not in ('x.bimcraft',) and f not in [os.path.basename(x) for x in files]:
        print(' [file %s]' % f)
        print(open(os.path.join(d, f), 'rb').read().decode('utf-8', 'replace'))
shutil.rmtree(d)

