#!/usr/bin/env python3
"""Compare the original and mine on many sessions.
usage: batch.py [-v] sessions_file [-f file]...
sessions file: JSON list of sessions; a session is a list of command strings (each `id {json}`),
optionally a dict {"cmds": [...], "files": [...], "save": true/false}.
Each session runs `run --cmd c1 --cmd c2 ... --save x.bimcraft` in a fresh dir.
"""
import os, re, subprocess, sys, tempfile, shutil, json, difflib
ORIG = '/workspace/executable'
MINE = os.environ.get('MINE', '/tmp/styles-agent/fills/repo/target/release/bimcraft-cli')
GUID = re.compile(r'[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}')
def norm(s):
    s = re.sub(r'"uid": \d+', '"uid": <UID>', s)
    m = {}
    def rep(mo):
        g = mo.group(0)
        if g not in m: m[g] = 'GUID-%d' % (len(m) + 1)
        return m[g]
    s = GUID.sub(rep, s)
    s = re.sub(r"\.tmp[A-Za-z0-9]{6}", ".tmpXXXXXX", s)
    s = re.sub(r"/tmp/b[a-z0-9_]{8}", "/tmp/DIR", s)
    return s
def run(exe, sess):
    d = tempfile.mkdtemp(prefix='b')
    for f in sess.get('files', []):
        shutil.copy(f, d)
    args = [exe, 'run']
    for c in sess['cmds']:
        args += ['--cmd', c]
    if sess.get('save', True):
        args += ['--save', 'x.bimcraft']
    p = subprocess.run(args, cwd=d, capture_output=True, timeout=120)
    out = {'code': str(p.returncode), 'stdout': p.stdout.decode('utf-8', 'replace'), 'stderr': p.stderr.decode('utf-8', 'replace')}
    for root, dirs, fs in os.walk(d):
        for f in fs:
            full = os.path.join(root, f)
            rel = os.path.relpath(full, d)
            if rel in [os.path.basename(x) for x in sess.get('files', [])]:
                continue
            out['file ' + rel] = open(full, 'rb').read().decode('utf-8', 'replace')
    shutil.rmtree(d)
    return {k: norm(v) for k, v in out.items()}
a = sys.argv[1:]
verbose = False
if a and a[0] == '-v':
    verbose = True; a = a[1:]
sessions = json.load(open(a[0]))
nd = 0
for i, s in enumerate(sessions):
    if isinstance(s, list):
        s = {'cmds': s}
    o = run(ORIG, s)
    m = run(MINE, s)
    if o != m:
        nd += 1
        print('### session %d DIFFERS: %s' % (i, json.dumps(s['cmds'], ensure_ascii=False)[:400]))
        for k in sorted(set(o) | set(m)):
            x, y = o.get(k, '<none>'), m.get(k, '<none>')
            if x != y:
                print('  --- %s' % k)
                for l in list(difflib.unified_diff(x.splitlines(), y.splitlines(), 'orig', 'mine', lineterm='', n=1))[2:30]:
                    print('   ', l[:300])
    elif verbose:
        print('### session %d same' % i)
print('%d/%d sessions differ' % (nd, len(sessions)))

