NUMS = ['0', '1', '-1', '0.5', '-0.5', '2', '45', '90', '135', '-45', '360', '400', '1e1', '.5', '5.', '+1', '-0', '0.0', '1.25', '3.175',
        '0.01', '0.05', '0.04', '100000', '100001', '-100001', '1e-9', '1e12', 'x', '', ' 1 ', '\t2', 'inf', 'nan', '0x1', '1,5', '7.5e-1',
        '0.125', '-0.125', '25.4', '-25.4', '1E2', '1e', '-', '.', '00012', '3937.0078740157483', '0.0019685039370078744', '12.7', '-6.35']
NAMES = ['A', 'B', 'Sand', 'sand', 'Brick 225 x 75', 'Café', ' spaced ', 'X,desc', '', ' , d', 'Horizontal', 'Solid fill', 'Tile 300', 'a;b', '*star',
         'Ü\tT', 'long' * 70, 'N', 'Dup', 'Dup']
def num():
    if rnd.random() < 0.15:
        return repr(rnd.uniform(-500, 500))
    return rnd.choice(NUMS)
def data_line():
    k = rnd.choice([3, 4, 5, 5, 5, 5, 6, 7, 7, 8, 9, 11, 21, 22])
    f = [num() for _ in range(k)]
    if rnd.random() < 0.7:
        f[4 if k > 4 else 0] = rnd.choice(['1', '2', '0.5', '-1', '3.175', '0.25'])
    if rnd.random() < 0.5:
        f[0] = rnd.choice(['0', '45', '90', '135', '-30', '400'])
    s = ','.join(f)
    r = rnd.random()
    if r < 0.1:
        s += ' ; comment'
    elif r < 0.15:
        s = '  ' + s + '  '
    elif r < 0.18:
        s += ','
    return s
def pat_text():
    lines = []
    for _ in range(rnd.randint(0, 6)):
        r = rnd.random()
        if r < 0.1:
            lines.append(rnd.choice([';%UNITS=INCH', ';%UNITS=MM', ';%units=inches', ';%UNITS = INCH', ';%UNITS=IN']))
        elif r < 0.15:
            lines.append(rnd.choice([';%VERSION=3.0', '; comment', ';', '']))
        elif r < 0.2:
            lines.append(data_line())
        lines.append('*' + rnd.choice(NAMES))
        if rnd.random() < 0.4:
            lines.append(rnd.choice([';%TYPE=MODEL', ';%TYPE=DRAFTING', ';%TYPE=model', ';%TYPE = MODEL', ';%TYPE=BOGUS', ';%TYPE']))
        for _ in range(rnd.choice([0, 1, 1, 2, 2, 3, 4])):
            lines.append(data_line())
            if rnd.random() < 0.05:
                lines.append(rnd.choice([';%UNITS=INCH', ';%UNITS=MM', ';%TYPE=MODEL', '', '   ']))
    sep = rnd.choice(['\n', '\n', '\n', '\r\n', '\r'])
    t = sep.join(lines)
    if rnd.random() < 0.5:
        t += sep
    if rnd.random() < 0.05:
        t = '﻿' + t
    return t
def run(exe, text, replace):
    d = tempfile.mkdtemp(prefix='fz')
    p = {'text': text}
    if replace:
        p['replace'] = True
    args = [exe, 'run', '--cmd', 'import_fill_patterns ' + json.dumps(p), '--cmd', 'fill_pattern', '--cmd', 'export_fill_patterns', '--save', 'x.bimcraft']
    r = subprocess.run(args, cwd=d, capture_output=True)
    out = r.stdout.decode('utf-8', 'replace') + '\nERR:' + r.stderr.decode('utf-8', 'replace')
    try:
        doc = json.load(open(os.path.join(d, 'x.bimcraft')))
        lib = sorted((k, v['kind'], v['name']) for k, v in doc['library'].items())
        out += '\nLIB:' + json.dumps(lib) + '\nFP:' + json.dumps(doc['fill_patterns'])
    except Exception as e:
        out += '\nNOFILE'
    shutil.rmtree(d)
    return out
nd = 0
for i in range(n):
    t = pat_text()
    rep = rnd.random() < 0.3
    o = run(ORIG, t, rep)
    m = run(MINE, t, rep)
    if o != m:
        nd += 1
        if nd <= 5:
            print('### case %d (replace=%s) DIFFERS: %r' % (i, rep, t[:500]))
            import difflib
            for l in list(difflib.unified_diff(o.splitlines(), m.splitlines(), 'orig', 'mine', lineterm='', n=0))[:12]:
                print('   ', l[:400])
print('seed %d: %d/%d differ' % (seed, nd, n))

