1	//! Fill patterns and filled region types: `fill_pattern`, `filled_region_type`, `import_fill_patterns`,
2	//! `export_fill_patterns`.
3	//!
4	//! The file keeps `fill_patterns` (by name: `target`, `lines`, `drawn`) and `region_types` (by name:
5	//! `foreground`, `foreground_color`, `background`, `background_color`, `masking`), both sorted by name;
6	//! a region type names its patterns, and a filled region its type, by the GUID of the library entry
7	//! (`fill-pattern`, `filled-region-type`), so a rename is the entry's and what names it follows.
8	
9	use super::common::*;
10	use super::pat;
11	use crate::json::{Map, Value};
12	use crate::project::Project;
13	use crate::session::Session;
14	
15	const FP: &str = "fill_pattern";
16	const RT: &str = "filled_region_type";
17	const KIND_FP: &str = "fill-pattern";
18	const KIND_RT: &str = "filled-region-type";
19	
20	/// The longest error the original gives whole; past it, the rest is counted.
21	const MAX_ERROR: usize = 2000;
22	
23	pub fn run(s: &mut Session, cid: &str, p: &Value) -> R<Value> {
24	    let r = match cid {
25	        "fill_pattern" => fill_pattern(s, p),
26	        "import_fill_patterns" => import(s, p),
27	        "export_fill_patterns" => export(s, p),
28	        "filled_region_type" => region_type(s, p),
29	        _ => Err(format!("{}: not supported here", cid)),
30	    };
31	    r.map_err(clip_error)
32	}
33	
34	/// Marks an error the original's model check gives (after the command), which isn't clipped.
35	const CHECK: char = '\u{1}';
36	
37	fn check_error(e: String) -> String {
38	    format!("{}{}", CHECK, e)
39	}
40	
41	/// A command's error past 2000 characters: its first 2000 and how many more there were (what the
42	/// model's check finds is said whole).
43	fn clip_error(e: String) -> String {
44	    if let Some(rest) = e.strip_prefix(CHECK) {
45	        return rest.to_string();
46	    }
47	    let n = e.chars().count();
48	    if n <= MAX_ERROR {
49	        return e;
50	    }
51	    let mut out: String = e.chars().take(MAX_ERROR).collect();
52	    out.push_str(&format!("… ({} more characters)", n - MAX_ERROR));
53	    out
54	}
55	
