57	
58	/// A family of parallel lines: at `angle` degrees through `origin`, `spacing` apart, each `shift`
59	/// along from the last, dashed by `dashes` (a dash's length, a space's as a negative one, 0 a dot).
60	#[derive(Clone, Debug, PartialEq)]
61	pub struct Hatch {
62	    pub angle: f64,
63	    pub origin: [f64; 2],
64	    pub shift: f64,
65	    pub spacing: f64,
66	    pub dashes: Vec<f64>,
67	}
68	
69	/// A fill pattern: drafting (mm on paper) or model (mm in the building), its families (none: solid),
70	/// and the scale of the view a made one was drawn in.
71	#[derive(Clone, Debug, PartialEq)]
72	pub struct Pattern {
73	    pub model: bool,
74	    pub lines: Vec<Hatch>,
75	    pub drawn: Option<f64>,
76	}
77	
78	fn num_in(v: Option<&Value>) -> f64 {
79	    v.and_then(|x| x.as_f64()).unwrap_or(0.0)
80	}
81	
82	impl Hatch {
83	    fn from_value(v: &Value) -> Hatch {
84	        let origin = match v.get("origin").and_then(|o| o.as_arr()) {
85	            Some(a) if a.len() == 2 => [a[0].as_f64().unwrap_or(0.0), a[1].as_f64().unwrap_or(0.0)],
86	            _ => [0.0, 0.0],
87	        };
88	        Hatch {
89	            angle: num_in(v.get("angle")),
90	            origin,
91	            shift: num_in(v.get("shift")),
92	            spacing: num_in(v.get("spacing")),
93	            dashes: v
94	                .get("dashes")
95	                .and_then(|d| d.as_arr())
96	                .map(|a| a.iter().filter_map(|x| x.as_f64()).collect())
97	                .unwrap_or_default(),
98	        }
99	    }
100	
101	    /// As the file holds it: the origin, the shift and the dashes only where they aren't nothing.
102	    fn to_value(&self) -> Value {
103	        let mut m = Map::new();
104	        m.insert("angle", Value::f(self.angle));
105	        if !(self.origin[0] == 0.0 && self.origin[1] == 0.0) {
106	            m.insert("origin", Value::Arr(vec![Value::f(self.origin[0]), Value::f(self.origin[1])]));
107	        }
108	        if self.shift != 0.0 {
109	            m.insert("shift", Value::f(self.shift));
110	        }
111	        m.insert("spacing", Value::f(self.spacing));
112	        if !self.dashes.is_empty() {
113	            m.insert("dashes", Value::Arr(self.dashes.iter().map(|d| Value::f(*d)).collect()));
114	        }
115	        Value::Obj(m)
116	    }
117	
118	    fn scale(&mut self, k: f64) {
119	        self.origin = [self.origin[0] * k, self.origin[1] * k];
120	        self.shift *= k;

