137	    /// As the file holds it (and replies give it): `target`, `lines` unless solid, `drawn` if any.
138	    pub fn to_value(&self) -> Value {
139	        let mut m = Map::new();
140	        m.insert("target", Value::s(if self.model { "model" } else { "drafting" }));
141	        if !self.lines.is_empty() {
142	            m.insert("lines", Value::Arr(self.lines.iter().map(|h| h.to_value()).collect()));
