150	    /// The pattern's rules, as a pattern `name` breaks them.
151	    pub fn check(&self, name: &str) -> R<()> {
152	        if let Some(d) = self.drawn {
153	            if !(d > 0.0 && d <= 100000.0) {
154	                return Err(format!(
155	                    "fill pattern `{}`: the scale it was drawn at is a number above 0, at most 100000",
156	                    name
157	                ));
158	            }
159	        }
160	        if self.lines.len() > pat::MAX_FAMILIES {
161	            return Err(format!(
162	                "fill pattern `{}`: {} line families, more than {}",
163	                name,
164	                self.lines.len(),
165	                pat::MAX_FAMILIES
166	            ));
167	        }
168	        for (i, h) in self.lines.iter().enumerate() {
169	            let at = format!("fill pattern `{}` line {}", name, i + 1);
170	            let finite = h.angle.is_finite() && h.origin[0].is_finite() && h.origin[1].is_finite() && h.shift.is_finite();
171	            if !(finite && h.shift.abs() <= 100000.0) {
172	                return Err(format!("{}: its angle, origin and shift are numbers, the shift within 100000", at));
173	            }
174	            if h.origin[0].abs() > 100000.0 || h.origin[1].abs() > 100000.0 {
175	                return Err(format!("{}: its origin is within 100000 of the pattern's", at));
176	            }
177	            if !(h.spacing >= 0.05 && h.spacing <= 100000.0) {
178	                return Err(format!("{}: its lines are 0.05 to 100000 apart, not {}", at, disp(h.spacing)));
179	            }
180	            if h.dashes.len() > pat::MAX_DASHES {
181	                return Err(format!("{}: {} dashes and spaces, more than {}", at, h.dashes.len(), pat::MAX_DASHES));
182	            }
183	            if !h.dashes.is_empty() {
184	                if h.dashes.iter().any(|d| !(d.abs() <= 100000.0)) {
185	                    return Err(format!("{}: a dash or a space is a length within 100000", at));
186	                }
187	                let dash = h.dashes.iter().any(|d| *d >= 0.0);
188	                let space = h.dashes.iter().any(|d| *d < 0.0);
189	                let total: f64 = h.dashes.iter().map(|d| d.abs()).sum();
190	                if !(dash && space && total >= 0.05) {
191	                    return Err(format!(
192	                        "{}: dashes need a dash (0 is a dot) and a space (a negative length) among them, and 0.05 or more in all",
193	                        at
194	                    ));
195	                }
196	            }
197	        }
198	        Ok(())
199	    }
200	}
