204	const LINES_FORM: &str = "`lines` is [{angle, spacing, origin?: [x, y], shift?, dashes?: [mm, -mm, …]}, …]";
205	
206	/// A map's entries in the order serde visits a JSON object's (sorted by key).
207	fn sorted_items(m: &Map) -> Vec<(&String, &Value)> {
208	    let mut v: Vec<(&String, &Value)> = m.items.iter().map(|(k, v)| (k, v)).collect();
209	    v.sort_by(|a, b| a.0.cmp(b.0));
210	    v
211	}
212	
213	fn de_f64(v: &Value) -> R<f64> {
214	    match v {
215	        Value::Num(n) => Ok(n.as_f64()),
216	        _ => Err(invalid_type(v, "f64")),
217	    }
218	}
219	
220	fn de_p2(v: &Value) -> R<[f64; 2]> {
221	    let a = match v {
222	        Value::Arr(a) => a,
223	        _ => return Err(invalid_type(v, "tuple struct P2")),
224	    };
225	    let mut out = [0.0; 2];
226	    for (i, slot) in out.iter_mut().enumerate() {
227	        match a.get(i) {
228	            Some(x) => *slot = de_f64(x)?,
229	            None => return Err(format!("invalid length {}, expected tuple struct P2 with 2 elements", i)),
230	        }
231	    }
232	    if a.len() > 2 {
233	        return Err(format!("invalid length {}, expected fewer elements in array", a.len()));
234	    }
235	    Ok(out)
236	}
237	
238	fn de_seq_f64(v: &Value) -> R<Vec<f64>> {
239	    match v {
240	        Value::Arr(a) => a.iter().map(de_f64).collect(),
241	        _ => Err(invalid_type(v, "a sequence")),
242	    }
243	}
244	
245	fn de_hatch(v: &Value) -> R<Hatch> {
246	    let m = match v {
247	        Value::Obj(m) => m,
248	        _ => return Err(invalid_type(v, "struct HatchLine")),
249	    };
250	    let (mut angle, mut spacing) = (None, None);
251	    let mut h = Hatch { angle: 0.0, origin: [0.0, 0.0], shift: 0.0, spacing: 0.0, dashes: Vec::new() };
252	    for (k, x) in sorted_items(m) {
253	        match k.as_str() {
254	            "angle" => angle = Some(de_f64(x)?),
255	            "origin" => h.origin = de_p2(x)?,
256	            "shift" => h.shift = de_f64(x)?,
257	            "spacing" => spacing = Some(de_f64(x)?),
258	            "dashes" => h.dashes = de_seq_f64(x)?,
259	            _ => {
260	                return Err(format!(
261	                    "unknown field `{}`, expected one of `angle`, `origin`, `shift`, `spacing`, `dashes`",
262	                    k
263	                ))
264	            }
265	        }
266	    }
267	    h.angle = angle.ok_or_else(|| "missing field `angle`".to_string())?;
268	    h.spacing = spacing.ok_or_else(|| "missing field `spacing`".to_string())?;
269	    Ok(h)
270	}
