272	/// `lines`, as serde reads a Vec of hatch lines (null or absent: None).
273	fn lines_param(p: &Value) -> R<Option<Vec<Hatch>>> {
274	    match p.get("lines") {
275	        None | Some(Value::Null) => Ok(None),
276	        Some(Value::Arr(a)) => a
277	            .iter()
278	            .map(de_hatch)
279	            .collect::<R<Vec<Hatch>>>()
280	            .map(Some)
281	            .map_err(|e| format!("{}: {}: {}", FP, LINES_FORM, e)),
282	        Some(v) => Err(format!("{}: {}: {}", FP, LINES_FORM, invalid_type(v, "a sequence"))),
283	    }
284	}
