286	/// `target`, as serde reads a unit enum (a string, or a map of one key to null).
287	fn target_param(p: &Value) -> R<Option<bool>> {
288	    let err = |e: String| format!("{}: `target` is drafting or model: {}", FP, e);
289	    let variant = |s: &str| match s {
290	        "drafting" => Ok(false),
291	        "model" => Ok(true),
292	        _ => Err(format!("unknown variant `{}`, expected `drafting` or `model`", s)),
293	    };
294	    match p.get("target") {
295	        None | Some(Value::Null) => Ok(None),
296	        Some(Value::Str(s)) => variant(s).map(Some).map_err(err),
297	        Some(Value::Obj(m)) => {
298	            if m.len() != 1 {
299	                return Err(err("invalid value: map, expected map with a single key".into()));
300	            }
301	            let (k, v) = &m.items[0];
302	            let t = variant(k).map_err(err)?;
303	            if !v.is_null() {
304	                return Err(err(invalid_type(v, "unit")));
305	            }
306	            Ok(Some(t))
307	        }
308	        Some(v) => Err(err(invalid_type(v, "string or map"))),
309	    }
310	}
