315	        None => Ok(None),
316	        Some(Value::Null) => Ok(Some(None)),
317	        Some(Value::Num(n)) => Ok(Some(Some(n.as_f64()))),
318	        Some(v) => Err(format!("{}: `drawn` is a view's scale, a number, not {}", FP, v.to_compact())),
319	    }
