322	/// `names`, as serde reads a Vec of strings (null or absent: None).
323	fn names_param(p: &Value, cmd: &str) -> R<Option<Vec<String>>> {
324	    let err = |e: String| format!("{}: `names` is [name, …]: {}", cmd, e);
325	    match p.get("names") {
326	        None | Some(Value::Null) => Ok(None),
327	        Some(Value::Arr(a)) => a
328	            .iter()
329	            .map(|x| match x {
330	                Value::Str(s) => Ok(s.clone()),
331	                _ => Err(err(invalid_type(x, "a string"))),
332	            })
333	            .collect::<R<Vec<String>>>()
334	            .map(Some),
335	        Some(v) => Err(err(invalid_type(v, "a sequence"))),
336	    }
