339	/// A text parameter as `opt_text` reads it, but untrimmed and kept when empty (a path).
340	fn raw_text(p: &Value, cmd: &str, key: &str) -> R<Option<String>> {
341	    match p.get(key) {
342	        None | Some(Value::Null) => Ok(None),
343	        Some(Value::Str(s)) if s.chars().count() <= 256 => Ok(Some(s.clone())),
344	        Some(v) => Err(format!("{}: `{}` must be text of at most 256 characters, got {}", cmd, key, v.to_compact())),
345	    }
346	}
