379	// ---------------------------------------------------------------- fill_pattern
380	
381	fn fill_pattern(s: &mut Session, p: &Value) -> R<Value> {
382	    check_keys(p, FP, &["name", "target", "lines", "drawn", "rename", "delete"])?;
383	    let pr = &mut s.project;
384	    let Some(name) = opt_name(p, FP, "name")? else {
385	        let mut all = Map::new();
386	        for (k, v) in patterns(pr).iter() {
387	            all.insert(k, Pattern::from_value(v).to_value());
388	        }
389	        return Ok(jobj! {"patterns" => Value::Obj(all)});
390	    };
391	    if opt_bool(p, FP, "delete")? == Some(true) {
392	        return delete_pattern(pr, &name);
393	    }
394	    let drawn = drawn_param(p)?;
395	    let lines = lines_param(p)?;
396	    let target = target_param(p)?;
397	    let rename = opt_name(p, FP, "rename")?;
398	    let all = patterns(pr);
399	    let existing = all.get(&name).map(Pattern::from_value);
400	    if existing.is_none() && lines.is_none() && target.is_none() {
401	        let names = pattern_names(pr);
402	        return Err(if names.is_empty() {
403	            format!("{}: there's no fill pattern `{}`; make one with `lines`", FP, name)
404	        } else {
405	            format!("{}: there's no fill pattern `{}`; make one with `lines` (there are: {})", FP, name, names.join(", "))
406	        });
407	    }
408	    if let Some(r) = &rename {
409	        if *r != name && all.contains(r) {
410	            return Err(format!("{}: there's already a fill pattern `{}`", FP, r));
411	        }
412	    }
413	    let is_new = existing.is_none();
414	    let mut pat = existing.unwrap_or(Pattern { model: false, lines: Vec::new(), drawn: None });
415	    if let Some(d) = drawn {
416	        pat.drawn = d;
417	    }
418	    let lines_given = lines.is_some();
419	    if let Some(l) = lines {
420	        pat.lines = l;
421	    }
422	    if let Some(model) = target {
423	        // a made pattern given another target and no lines is the same drawing, rescaled
424	        if !is_new && !lines_given && model != pat.model {
425	            if let Some(n) = pat.drawn {
426	                let k = if model { n } else { 1.0 / n };
427	                for h in &mut pat.lines {
428	                    h.scale(k);
429	                }
430	            }
431	        }
432	        pat.model = model;
433	    }
434	    let final_name = rename.clone().unwrap_or_else(|| name.clone());
435	    pat.check(&final_name).map_err(|e| format!("{}: {}", FP, e))?;
436	    let sec = pr.section_mut("fill_patterns");
437	    if final_name != name {
438	        sec.remove(&name);
439	    }
440	    sec.insert_sorted(&final_name, pat.to_value());
441	    if final_name != name {
442	        lib_rename(pr, KIND_FP, &name, &final_name);
443	    }
444	    lib_ensure(pr, KIND_FP, &final_name);
445	    super::mark_step();
446	    Ok(jobj! {"name" => final_name, "pattern" => pat.to_value()})
447	}
448	
449	fn delete_pattern(pr: &mut Project, name: &str) -> R<Value> {
450	    if !patterns(pr).contains(name) {
451	        return Err(format!("{}: there's no fill pattern `{}`", FP, name));
452	    }
453	    let g = pattern_guid(pr, name).unwrap_or_default();
454	    if !g.is_empty() {
455	        for (t, v) in section(pr, "region_types").iter() {
456	            let fg = v.get("foreground").and_then(|x| x.as_str()) == Some(g.as_str());
457	            let bg = v.get("background").and_then(|x| x.as_str()) == Some(g.as_str());
458	            if fg || bg {
459	                return Err(format!("{}: filled region type `{}` fills with `{}`; give it another first", FP, t, name));
460	            }
461	        }
462	        let mut mats: Vec<(String, Value)> = section(pr, "materials").items;
463	        mats.sort_by(|a, b| a.0.cmp(&b.0));
464	        for (m, v) in &mats {
465	            let cut = v.get("cut_pattern").and_then(|x| x.as_str()) == Some(g.as_str());
466	            let surface = v.get("surface_pattern").and_then(|x| x.as_str()) == Some(g.as_str());
467	            if cut || surface {
468	                return Err(format!("{}: material `{}` shows `{}`; give it another first", FP, m, name));
469	            }
470	        }
471	        // what the model's check then finds: views and templates overriding with it
472	        let mut templates: Vec<(String, Value)> = section(pr, "view_templates").items;
473	        templates.sort_by(|a, b| a.0.cmp(&b.0));
474	        for (t, v) in &templates {
475	            if v.get("graphics").map(|gr| holds(gr, &g)).unwrap_or(false) {
476	                return Err(check_error(format!("view template `{}`: there's no fill pattern `{}`", t, name)));
477	            }
478	        }
479	        for (id, e) in &pr.elements {
480	            if e.get("graphics").map(|gr| holds(gr, &g)).unwrap_or(false) {
481	                let cat = e.get("category").and_then(|c| c.as_str()).unwrap_or("element");
482	                return Err(check_error(format!("{} {}: there's no fill pattern `{}`", cat, id, name)));
483	            }
484	        }
485	    }
486	    pr.section_mut("fill_patterns").remove(name);
487	    lib_remove(pr, KIND_FP, name);
488	    super::mark_step();
489	    Ok(jobj! {"deleted" => name})
490	}
