492	// ---------------------------------------------------------------- PAT files
493	
494	fn import(s: &mut Session, p: &Value) -> R<Value> {
495	    const C: &str = "import_fill_patterns";
496	    check_keys(p, C, &["path", "text", "replace"])?;
497	    let replace = opt_bool(p, C, "replace")?.unwrap_or(false);
498	    let text = match p.get("text") {
499	        None | Some(Value::Null) => None,
500	        Some(Value::Str(t)) => Some(t.clone()),
501	        Some(_) => return Err(format!("{}: `text` must be the text of a PAT file", C)),
502	    };
503	    let path = raw_text(p, C, "path")?;
504	    let text = match (path, text) {
505	        (Some(path), None) => {
506	            let meta = std::fs::metadata(&path).map_err(|e| format!("{}: {}: {}", C, path, e))?;
507	            if meta.is_file() && meta.len() > pat::MAX_FILE {
508	                return Err(format!("{}: {} is too large ({} bytes)", C, path, meta.len()));
509	            }
510	            let bytes = std::fs::read(&path).map_err(|e| format!("{}: {}: {}", C, path, e))?;
511	            if bytes.len() as u64 > pat::MAX_FILE {
512	                return Err(format!("{}: {} is too large ({} bytes)", C, path, bytes.len()));
513	            }
514	            pat::decode(&bytes)
515	        }
516	        (None, Some(t)) => t,
517	        _ => return Err(format!("{}: give `path`, a PAT file, or its `text`", C)),
518	    };
519	    let file = pat::parse(&text);
520	    let pr = &mut s.project;
521	    let had: Vec<String> = pattern_names(pr);
522	    // what the file itself can't give comes after what the project already has
523	    let mut seen: Vec<String> = Vec::new();
524	    let mut valid: Vec<(String, Pattern)> = Vec::new();
525	    let mut unfit: Vec<Value> = Vec::new();
526	    for r in file.patterns {
527	        let why = match r.pattern {
528	            Err(e) => Some(e),
529	            Ok(pt) => match pt.check(&r.name) {
530	                Err(e) => Some(e),
531	                Ok(()) if seen.contains(&r.name) => Some("the file has it twice".to_string()),
532	                Ok(()) => {
533	                    seen.push(r.name.clone());
534	                    valid.push((r.name.clone(), pt));
535	                    None
536	                }
537	            },
538	        };
539	        if let Some(w) = why {
540	            unfit.push(jobj! {"name" => r.name.clone(), "why" => w});
541	        }
542	    }
543	    let mut imported: Vec<(String, Pattern)> = Vec::new();
544	    let mut left: Vec<Value> = Vec::new();
545	    for (n, pt) in valid {
546	        if had.contains(&n) && !replace {
547	            left.push(jobj! {"name" => n, "why" => "the project has a pattern of that name"});
548	        } else {
549	            imported.push((n, pt));
550	        }
551	    }
552	    left.extend(unfit);
553	    let count = left.len() + file.unread;
554	    if file.unread > 0 {
555	        left.push(jobj! {
556	            "name" => format!("{} more", file.unread),
557	            "why" => format!("the file holds more than {} patterns; the rest weren't read", pat::MAX_PATTERNS),
558	        });
559	    }
560	    left.truncate(100);
561	    let mut new_names: Vec<String> = Vec::new();
562	    for (n, pt) in &imported {
563	        pr.section_mut("fill_patterns").insert_sorted(n, pt.to_value());
564	        if pattern_guid(pr, n).is_none() && !new_names.contains(n) {
565	            new_names.push(n.clone());
566	        }
567	    }
568	    new_names.sort();
569	    for n in &new_names {
570	        lib_ensure(pr, KIND_FP, n);
571	    }
572	    super::mark_step();
573	    let names: Vec<Value> = imported.iter().map(|(n, _)| Value::s(n)).collect();
574	    Ok(jobj! {"imported" => Value::Arr(names), "left_out" => Value::Arr(left), "left_out_count" => count})
575	}
