577	fn export(s: &mut Session, p: &Value) -> R<Value> {
578	    const C: &str = "export_fill_patterns";
579	    check_keys(p, C, &["path", "names"])?;
580	    let pr = &s.project;
581	    let names = names_param(p, C)?;
582	    let all = patterns(pr);
583	    if let Some(ns) = &names {
584	        for n in ns {
585	            if !all.contains(n) {
586	                return Err(format!("{}: there's no fill pattern `{}`", C, n));
587	            }
588	        }
589	    }
590	    let path = raw_text(p, C, "path")?;
591	    let mut chosen: Vec<(String, Pattern)> = all
592	        .iter()
593	        .filter(|(k, _)| names.as_ref().map(|ns| ns.contains(k)).unwrap_or(true))
594	        .map(|(k, v)| (k.clone(), Pattern::from_value(v)))
595	        .collect();
596	    chosen.sort_by(|a, b| a.0.cmp(&b.0));
597	    let text = pat::write(chosen.iter().map(|(k, v)| (k.as_str(), v)));
598	    match path {
599	        None => Ok(jobj! {"text" => text}),
600	        Some(path) => {
601	            write_persist(&path, text.as_bytes()).map_err(|e| format!("{}: {}: {}", C, path, e))?;
602	            Ok(jobj! {"path" => path})
603	        }
604	    }
605	}
