607	/// Writes a file as the tempfile crate's persist does: a hidden file beside it, renamed over it,
608	/// with that crate's errors.
609	fn write_persist(path: &str, bytes: &[u8]) -> Result<(), String> {
610	    use std::io::Write;
611	    use std::os::unix::fs::OpenOptionsExt;
612	    let p = std::path::Path::new(path);
613	    let parent = match p.parent() {
614	        Some(d) if !d.as_os_str().is_empty() => d.to_path_buf(),
615	        _ => std::path::PathBuf::from(""),
616	    };
617	    let dir = if parent.is_absolute() {
618	        parent
619	    } else {
620	        std::env::current_dir().map_err(|e| e.to_string())?.join(parent)
621	    };
622	    let tmp = dir.join(format!(".tmp{}", crate::rand::alnum(6)));
623	    let at = |e: std::io::Error| format!("{} at path {:?}", e, tmp.to_string_lossy());
624	    let mut f = std::fs::OpenOptions::new().write(true).create_new(true).mode(0o600).open(&tmp).map_err(at)?;
625	    if let Err(e) = f.write_all(bytes) {
626	        drop(f);
627	        let _ = std::fs::remove_file(&tmp);
628	        return Err(at(e));
629	    }
630	    drop(f);
631	    std::fs::rename(&tmp, p).map_err(|e| {
632	        let _ = std::fs::remove_file(&tmp);
633	        format!("failed to persist temporary file: {}", e)
634	    })
635	}
