652	/// A region type as replies give it: its patterns by name.
653	fn type_reply(pr: &Project, v: &Value) -> Value {
654	    let mut m = Map::new();
655	    for key in ["foreground", "background"] {
656	        if let Some(g) = v.get(key).and_then(|x| x.as_str()) {
657	            if let Some(n) = pattern_of_guid(pr, g) {
658	                m.insert(key, Value::s(&n));
659	            }
660	        }
661	        let ck = format!("{}_color", key);
662	        m.insert(&ck, color_value(color_in(v.get(&ck))));
663	    }
664	    if v.get("masking").and_then(|x| x.as_bool()) == Some(true) {
665	        m.insert("masking", Value::Bool(true));
666	    }
667	    Value::Obj(m)
668	}
669	
670	/// A region type's pattern by name, as its library GUID (None: not given; Some(None): none).
671	fn resolve_pattern(pr: &mut Project, want: &Option<Option<String>>, type_name: &str) -> R<Option<Option<String>>> {
672	    match want {
673	        Some(Some(n)) => {
674	            if patterns(pr).contains(n) {
675	                Ok(Some(Some(lib_ensure(pr, KIND_FP, n))))
676	            } else {
677	                Err(format!(
678	                    "{}: filled region type `{}`: there's no fill pattern `{}` (there are: {})",
679	                    RT,
680	                    type_name,
681	                    n,
682	                    pattern_names(pr).join(", ")
683	                ))
684	            }
685	        }
686	        Some(None) => Ok(Some(None)),
687	        None => Ok(None),
688	    }
689	}
690	
691	fn region_type(s: &mut Session, p: &Value) -> R<Value> {
692	    check_keys(
693	        p,
694	        RT,
695	        &["name", "foreground", "foreground_color", "background", "background_color", "masking", "rename", "delete"],
696	    )?;
697	    let pr = &mut s.project;
698	    let types = section(pr, "region_types");
699	    let Some(name) = opt_name(p, RT, "name")? else {
700	        let mut all = Map::new();
701	        for (k, v) in types.iter() {
702	            all.insert(k, type_reply(pr, v));
703	        }
704	        return Ok(jobj! {"types" => Value::Obj(all)});
705	    };
706	    if opt_bool(p, RT, "delete")? == Some(true) {
707	        return delete_type(pr, &name);
708	    }
709	    let fg = pattern_param(p, "foreground")?;
710	    let bg = pattern_param(p, "background")?;
711	    let fgc = opt_color(p, RT, "foreground_color")?;
712	    let bgc = opt_color(p, RT, "background_color")?;
713	    let masking = opt_bool(p, RT, "masking")?;
714	    let rename = opt_name(p, RT, "rename")?;
715	    if let Some(r) = &rename {
716	        if *r != name && types.contains(r) {
717	            return Err(format!("{}: there's already a filled region type `{}`", RT, r));
718	        }
719	    }
720	    let final_name = rename.clone().unwrap_or_else(|| name.clone());
721	    let fg_g = resolve_pattern(pr, &fg, &final_name)?;
722	    let bg_g = resolve_pattern(pr, &bg, &final_name)?;
723	    let old = types.get(&name).cloned().unwrap_or_else(Value::obj);
724	    let pick = |key: &str, given: &Option<Option<String>>| -> Option<String> {
725	        match given {
726	            Some(x) => x.clone(),
727	            None => old.get(key).and_then(|x| x.as_str()).map(|x| x.to_string()),
728	        }
729	    };
730	    let fore = pick("foreground", &fg_g);
731	    let back = pick("background", &bg_g);
732	    let fore_c = fgc.unwrap_or_else(|| color_in(old.get("foreground_color")));
733	    let back_c = bgc.unwrap_or_else(|| color_in(old.get("background_color")));
734	    let mask = masking.unwrap_or(old.get("masking").and_then(|x| x.as_bool()) == Some(true));
735	    let mut m = Map::new();
736	    if let Some(g) = &fore {
737	        m.insert("foreground", Value::s(g));
738	    }
739	    m.insert("foreground_color", color_value(fore_c));
740	    if let Some(g) = &back {
741	        m.insert("background", Value::s(g));
742	    }
743	    m.insert("background_color", color_value(back_c));
744	    if mask {
745	        m.insert("masking", Value::Bool(true));
746	    }
747	    let v = Value::Obj(m);
748	    let sec = pr.section_mut("region_types");
749	    if final_name != name {
750	        sec.remove(&name);
751	    }
752	    sec.insert_sorted(&final_name, v.clone());
753	    if final_name != name {
754	        lib_rename(pr, KIND_RT, &name, &final_name);
755	    }
756	    lib_ensure(pr, KIND_RT, &final_name);
757	    super::mark_step();
758	    Ok(jobj! {"name" => final_name, "type" => type_reply(pr, &v)})
759	}
760	
761	fn delete_type(pr: &mut Project, name: &str) -> R<Value> {
762	    if !section(pr, "region_types").contains(name) {
763	        return Err(format!("{}: there's no filled region type `{}`", RT, name));
764	    }
765	    let g = guid_of(pr, KIND_RT, name).unwrap_or_default();
766	    if !g.is_empty() {
767	        for (id, e) in &pr.elements {
768	            if e.get("category").and_then(|c| c.as_str()) == Some("region")
769	                && e.get("type").and_then(|t| t.as_str()) == Some(g.as_str())
770	            {
771	                return Err(format!("{}: filled region {} is of `{}`; give it another type first", RT, id, name));
772	            }
773	        }
774	    }
775	    pr.section_mut("region_types").remove(name);
776	    lib_remove(pr, KIND_RT, name);
777	    if !g.is_empty() {
778	        // what the model's check then finds: detail groups whose members are of it
779	        let mut groups: Vec<(String, Value)> = section(pr, "detail_groups").items;
780	        groups.sort_by(|a, b| a.0.cmp(&b.0));
781	        for (gname, gv) in &groups {
782	            let members = gv.get("members").and_then(|m| m.as_arr()).cloned().unwrap_or_default();
783	            for (i, mem) in members.iter().enumerate() {
784	                let el = mem.get("element");
785	                let is_region = el.and_then(|e| e.get("category")).and_then(|c| c.as_str()) == Some("region");
786	                let of_it = el.and_then(|e| e.get("type")).and_then(|t| t.as_str()) == Some(g.as_str());
787	                if is_region && of_it {
788	                    let mut rest: Vec<String> = section(pr, "region_types").keys().cloned().collect();
789	                    rest.sort();
790	                    return Err(check_error(format!(
791	                        "detail group `{}` member {}: there's no filled region type `{}` (there are: {})",
792	                        gname,
793	                        i,
794	                        name,
795	                        rest.join(", ")
796	                    )));
797	                }
798	            }
799	        }
800	    }
801	    super::mark_step();
802	    Ok(jobj! {"deleted" => name})
803	}
