#!/usr/bin/env python3
"""Random fill_pattern / filled_region_type / export sessions run by both programs; report differences."""
import os, random, subprocess, sys, tempfile, shutil, json, re, difflib
ORIG = '/workspace/executable'
MINE = os.environ.get('MINE', '/tmp/styles-agent/fills/repo/target/release/bimcraft-cli')
seed = int(sys.argv[1]) if len(sys.argv) > 1 else 1
n = int(sys.argv[2]) if len(sys.argv) > 2 else 100
rnd = random.Random(seed)
GUID = re.compile(r'[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}')
def norm(s):
    s = re.sub(r'"uid": \d+', '"uid": <UID>', s)
    m = {}
    def rep(mo):
        g = mo.group(0)
        if g not in m: m[g] = 'GUID-%d' % (len(m) + 1)
        return m[g]
    return GUID.sub(rep, s)
PNAMES = ['Sand', 'Horizontal', 'Solid fill', 'Brick 225 x 75', 'P1', 'P2', 'p1', ' P1 ', '', 'Nope']
TNAMES = ['Sand', 'Brick', 'Masking', 'Solid Black', 'T1', 'T2', ' T1 ', '', 'Nope']
def rnum():
    return rnd.choice([0, 1, -1, 0.5, 1.5, 2, 45, 90, -30, 400, 1e-9, 0.05, 0.04, 1e5, 1e6, 100000.5, 3, 0.3, 25.4, rnd.uniform(-10, 10)])
def rval():
    return rnd.choice([None, True, 'x', 3, -1, 1.5, [], {}, [1], [1, 2], [1, 2, 3], {'a': 1}, '', ' '])
def rline():
    if rnd.random() < 0.1:
        return rval()
    d = {}
    if rnd.random() < 0.95: d['angle'] = rnum() if rnd.random() < 0.9 else rval()
    if rnd.random() < 0.95: d['spacing'] = rnum() if rnd.random() < 0.9 else rval()
    if rnd.random() < 0.3: d['shift'] = rnum() if rnd.random() < 0.9 else rval()
    if rnd.random() < 0.3: d['origin'] = [rnum(), rnum()] if rnd.random() < 0.8 else rval()
    if rnd.random() < 0.4:
        d['dashes'] = [rnd.choice([1, -1, 0, 0.5, -0.5, 2, -0.01, 0.02]) for _ in range(rnd.choice([0, 1, 2, 2, 3, 4, 17]))] if rnd.random() < 0.9 else rval()
    if rnd.random() < 0.05: d['bogus'] = 1
    return d
def fp_cmd():
    d = {}
    if rnd.random() < 0.95: d['name'] = rnd.choice(PNAMES) if rnd.random() < 0.95 else rval()
    if rnd.random() < 0.4: d['target'] = rnd.choice(['drafting', 'model', 'Model', None, 3, {'model': None}])
    if rnd.random() < 0.5: d['lines'] = [rline() for _ in range(rnd.choice([0, 1, 1, 2, 3]))] if rnd.random() < 0.9 else rval()
    if rnd.random() < 0.3: d['drawn'] = rnd.choice([50, 100, 0.5, 0, -1, None, 'x', 3, 1e6])
    if rnd.random() < 0.2: d['rename'] = rnd.choice(PNAMES) if rnd.random() < 0.9 else rval()
    if rnd.random() < 0.15: d['delete'] = rnd.choice([True, False, 1, None])
    if rnd.random() < 0.03: d['bogus'] = 1
    return 'fill_pattern ' + json.dumps(d)
def rt_cmd():
    d = {}
    if rnd.random() < 0.95: d['name'] = rnd.choice(TNAMES) if rnd.random() < 0.95 else rval()
    for k in ['foreground', 'background']:
        if rnd.random() < 0.3: d[k] = rnd.choice(PNAMES + [None]) if rnd.random() < 0.9 else rval()
    for k in ['foreground_color', 'background_color']:
        if rnd.random() < 0.2: d[k] = rnd.choice(['#ff0000', [1, 2, 3], 'red', [256, 0, 0], None, '#ABCDEF'])
    if rnd.random() < 0.2: d['masking'] = rnd.choice([True, False, None, 1])
    if rnd.random() < 0.2: d['rename'] = rnd.choice(TNAMES) if rnd.random() < 0.9 else rval()
    if rnd.random() < 0.15: d['delete'] = rnd.choice([True, False, 1, None])
    if rnd.random() < 0.03: d['bogus'] = 1
    return 'filled_region_type ' + json.dumps(d)
def other():
    return rnd.choice(['fill_pattern', 'filled_region_type', 'export_fill_patterns', 'undo', 'redo',
                       'export_fill_patterns {"names":["Sand","P1"]}', 'import_fill_patterns {"text":"*P1\\n0,0,0,0,1\\n*P2\\n45,0,0,0,2,1,-1"}',
                       'import_fill_patterns {"text":"*P1\\n0,0,0,0,3","replace":true}'])
def session():
    cmds = []
    for _ in range(rnd.randint(1, 6)):
        r = rnd.random()
        cmds.append(fp_cmd() if r < 0.45 else rt_cmd() if r < 0.8 else other())
    return cmds
def run(exe, cmds):
    d = tempfile.mkdtemp(prefix='fz2')
    out = []
    # run commands one by one in one session via a script file so errors don't stop the rest? errors stop a run;
    # so run as separate prefix sessions: each prefix k runs cmds[:k+1]
    args = [exe, 'run']
    for c in cmds:
        args += ['--cmd', c]
    args += ['--save', 'x.bimcraft']
    p = subprocess.run(args, cwd=d, capture_output=True)
    s = p.stdout.decode('utf-8', 'replace') + '\nERR:' + p.stderr.decode('utf-8', 'replace')
    if os.path.exists(os.path.join(d, 'x.bimcraft')):
        s += open(os.path.join(d, 'x.bimcraft')).read()
    shutil.rmtree(d)
    return norm(s)
nd = 0
for i in range(n):
    cmds = session()
    o = run(ORIG, cmds)
    m = run(MINE, cmds)
    if o != m:
        nd += 1
        if nd <= 5:
            print('### session %d DIFFERS: %s' % (i, json.dumps(cmds)[:600]))
            for l in list(difflib.unified_diff(o.splitlines(), m.splitlines(), 'orig', 'mine', lineterm='', n=0))[:12]:
                print('   ', l[:300])
print('seed %d: %d/%d differ' % (seed, nd, n))

