1	//! PAT files: reading AutoCAD's and Revit's fill pattern files, and writing them.
2	//!
3	//! A pattern is a header `*Name[, description]` and one line per family of parallel lines,
4	//! `angle, x, y, shift, offset[, dash, …]`; `;` starts a comment, `;%UNITS=INCH` makes the lines
5	//! read after it inches, `;%TYPE=MODEL` makes the pattern it is in a model one.
6	
7	use super::fills::{Hatch, Pattern};
8	
9	/// The most patterns a file is read for.
10	pub const MAX_PATTERNS: usize = 2000;
11	/// The most families of lines a pattern has.
12	pub const MAX_FAMILIES: usize = 256;
13	/// The most dashes and spaces a family has.
14	pub const MAX_DASHES: usize = 16;
15	/// The biggest PAT file `path` reads.
16	pub const MAX_FILE: u64 = 16 * 1024 * 1024;
17	
18	/// A pattern as a file gives it: its name, and the pattern or why it can't be one.
19	pub struct Read {
20	    pub name: String,
21	    pub pattern: Result<Pattern, String>,
22	}
23	
24	/// What a file holds: its patterns (the first 2000), and how many headers past them weren't read.
25	pub struct File {
26	    pub patterns: Vec<Read>,
27	    pub unread: usize,
28	}
29	
30	/// The text of a file's bytes: UTF-8 if they are, else Latin-1, a character a byte.
31	pub fn decode(bytes: &[u8]) -> String {
32	    match std::str::from_utf8(bytes) {
33	        Ok(s) => s.to_string(),
34	        Err(_) => bytes.iter().map(|b| *b as char).collect(),
35	    }
36	}
37	
38	/// A pattern's name from its header (what follows `*`, up to a comma).
39	fn header_name(rest: &str) -> String {
40	    let raw = rest.split(',').next().unwrap_or("");
41	    let clean: String = raw.trim().chars().filter(|c| !c.is_control()).collect();
42	    if clean.is_empty() {
43	        return "Unnamed".to_string();
44	    }
45	    clean.chars().take(256).collect()
46	}
47	
48	/// A line shown in a reason: at most 40 characters, then an ellipsis.
49	fn clip40(s: &str) -> String {
50	    if s.chars().count() > 40 {
51	        let mut out: String = s.chars().take(40).collect();
52	        out.push('…');
53	        out
54	    } else {
55	        s.to_string()
56	    }
57	}
58	
59	struct Building {
60	    name: String,
61	    model: bool,
62	    lines: Vec<Hatch>,
63	    error: Option<String>,
64	}
65	
66	impl Building {
67	    fn finish(self) -> Read {
68	        let pattern = match self.error {
69	            Some(e) => Err(e),
70	            None if self.lines.is_empty() => Err("it has no lines".to_string()),
71	            None => Ok(Pattern { model: self.model, lines: self.lines, drawn: None }),
72	        };
73	        Read { name: self.name, pattern }
74	    }
75	}
76	
77	/// One family of lines from a data line (its comment gone), in mm.
78	fn family(text: &str, scale: f64) -> Result<Hatch, String> {
79	    let fields: Vec<&str> = text.split(',').collect();
80	    if fields.len() > 5 + MAX_DASHES {
81	        return Err(format!("a family has more than {} dashes", MAX_DASHES));
82	    }
83	    let not_numbers = || {
84	        format!("`{}` isn't a line of numbers: angle, x, y, shift, offset and dashes", clip40(text))
85	    };
86	    if fields.len() < 5 {
87	        return Err(not_numbers());
88	    }
89	    let mut nums = Vec::with_capacity(fields.len());
90	    for f in &fields {
91	        match f.trim().parse::<f64>() {
92	            Ok(x) if x.is_finite() => nums.push(x),
93	            _ => return Err(not_numbers()),
94	        }
95	    }
96	    let (mut shift, mut offset) = (nums[3], nums[4]);
97	    if offset == 0.0 {
98	        return Err("a family's lines lie on each other: its offset is 0".to_string());
99	    }
100	    let dashes: Vec<f64> = nums[5..].to_vec();
101	    if !dashes.is_empty() && dashes.iter().all(|d| *d < 0.0) {
102	        return Err("a family's dashes are all spaces: it draws nothing".to_string());
103	    }
104	    if offset < 0.0 {
105	        offset = -offset;
106	        shift = -shift;
107	    }
108	    Ok(Hatch {
109	        angle: nums[0].rem_euclid(360.0),
110	        origin: [nums[1] * scale, nums[2] * scale],
111	        shift: shift * scale,
112	        spacing: offset * scale,
113	        dashes: dashes.iter().map(|d| d * scale).collect(),
114	    })
115	}
116	
117	/// Reads a PAT file's text: each pattern, or why it can't be one (in file order).
118	pub fn parse(text: &str) -> File {
119	    let mut out = File { patterns: Vec::new(), unread: 0 };
120	    let mut inch = false;
121	    let mut cur: Option<Building> = None;
122	    let mut headers = 0usize;
123	    for raw in text.split('\n') {
124	        // a line's byte order marks go with its leading blanks (one a file starts with among them)
125	        let t = raw.trim().trim_start_matches('\u{feff}');
126	        if t.is_empty() {
127	            continue;
128	        }
129	        if headers > MAX_PATTERNS {
130	            if t.starts_with('*') {
131	                out.unread += 1;
132	            }
133	            continue;
134	        }
135	        if let Some(rest) = t.strip_prefix(';') {
136	            if let Some(dir) = rest.strip_prefix('%') {
137	                let (k, v) = dir.split_once('=').unwrap_or((dir, ""));
138	                let (k, v) = (k.trim(), v.trim());
139	                if k.eq_ignore_ascii_case("UNITS") {
140	                    inch = v.eq_ignore_ascii_case("INCH") || v.eq_ignore_ascii_case("INCHES");
141	                } else if k.eq_ignore_ascii_case("TYPE") {
142	                    if let Some(b) = cur.as_mut() {
143	                        b.model = v.eq_ignore_ascii_case("MODEL");
144	                    }
145	                }
146	            }
147	            continue;
148	        }
149	        if let Some(rest) = t.strip_prefix('*') {
150	            headers += 1;
151	            if let Some(b) = cur.take() {
152	                out.patterns.push(b.finish());
153	            }
154	            if headers > MAX_PATTERNS {
155	                out.unread += 1;
156	                continue;
157	            }
158	            cur = Some(Building { name: header_name(rest), model: false, lines: Vec::new(), error: None });
159	            continue;
160	        }
161	        let Some(b) = cur.as_mut() else { continue };
162	        if b.error.is_some() {
163	            continue;
164	        }
165	        let data = t.split(';').next().unwrap_or("").trim();
166	        match family(data, if inch { 25.4 } else { 1.0 }) {
167	            Ok(h) => {
168	                if b.lines.len() >= MAX_FAMILIES {
169	                    b.error = Some(format!("more than {} line families", MAX_FAMILIES));
170	                } else {
171	                    b.lines.push(h);
172	                }
173	            }
174	            Err(e) => b.error = Some(e),
175	        }
176	    }
177	    if let Some(b) = cur.take() {
178	        out.patterns.push(b.finish());
179	    }
180	    out
181	}
182	
183	/// A number as a PAT file has it: to a millionth, without trailing zeros.
184	pub fn num(x: f64) -> String {
185	    let y = (x * 1e6).round() / 1e6;
186	    let y = if y == 0.0 { 0.0 } else { y };
187	    format!("{}", y)
188	}
189	
190	/// The PAT text of patterns, in mm; solid ones (no lines) left out.
191	pub fn write<'a>(patterns: impl Iterator<Item = (&'a str, &'a Pattern)>) -> String {
192	    let mut s = String::from(";%UNITS=MM\n;%VERSION=3.0\n;Fill patterns from BIMCraft\n");
193	    for (name, p) in patterns {
194	        if p.lines.is_empty() {
195	            continue;
196	        }
197	        // a name's commas and control characters would end it or its line: spaces stand in
198	        s.push('*');
199	        s.extend(name.chars().map(|c| if c == ',' || c.is_control() { ' ' } else { c }));
200	        s.push('\n');
201	        s.push_str(if p.model { ";%TYPE=MODEL\n" } else { ";%TYPE=DRAFTING\n" });
202	        for h in &p.lines {
